import { readFileSync } from "fs";

const [first, second] = readFileSync(0, "utf8").trim().split("\n");
const [, k] = first.split(" ").map(Number);
const ropes = second.split(" ").map(Number);

// 長さ x で K 本以上作れるか
const can = (x: number): boolean => {
  let pieces = 0;
  for (const len of ropes) pieces += Math.floor(len / x);
  return pieces >= k;
};

// 答えを二分探索する: lo は作れる長さ、hi は作れない長さ
let lo = 0;
let hi = 1_000_000_001;
while (hi - lo > 1) {
  const mid = Math.floor((lo + hi) / 2);
  if (can(mid)) lo = mid;
  else hi = mid;
}
